<?php
declare(strict_types=1);
function ensure_product_feature_schema(): void {static $ready=false;if($ready)return;query("CREATE TABLE IF NOT EXISTS ns_product_features (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,value VARCHAR(180) NOT NULL,icon VARCHAR(30) NOT NULL DEFAULT 'other',sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,INDEX(product_id,sort_order),FOREIGN KEY(product_id) REFERENCES ns_products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$ready=true;}
function feature_icon(string $icon): string {$paths=['dimensions'=>'<path d="M4 7V4h3M17 4h3v3M20 17v3h-3M7 20H4v-3M8 8l8 8M16 8l-8 8"/>','weight'=>'<path d="M7 20h10l2-12H5l2 12Zm2-12a3 3 0 0 1 6 0"/>','material'=>'<path d="M12 3 4 7l8 4 8-4-8-4Zm-8 9 8 4 8-4M4 17l8 4 8-4"/>','size'=>'<path d="M4 18 18 4M8 4H4v4M16 20h4v-4"/>','thickness'=>'<path d="m4 8 8-4 8 4-8 4-8-4Zm0 4 8 4 8-4M4 16l8 4 8-4"/>','color'=>'<path d="M12 3a9 9 0 1 0 0 18h1.5a1.5 1.5 0 0 0 0-3H12a2 2 0 0 1 0-4h2a7 7 0 0 0-2-11Z"/>','count'=>'<path d="M8 6h12M8 12h12M8 18h12M4 6h.01M4 12h.01M4 18h.01"/>','other'=>'<circle cx="12" cy="12" r="9"/><path d="M12 8v4l3 2"/>'];return '<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7">'.($paths[$icon]??$paths['other']).'</svg>';}
function product_features(int $productId): array {ensure_product_feature_schema();return all('SELECT * FROM ns_product_features WHERE product_id=? ORDER BY sort_order,id',[$productId]);}
function render_product_features(int $productId): void {$items=product_features($productId);if(!$items)return;?><section class="product-features" aria-labelledby="feature-heading"><h2 id="feature-heading">ویژگی‌های محصول</h2><div class="feature-grid"><?php foreach($items as$item):?><div class="feature-item"><span><?=feature_icon($item['icon'])?></span><div><small><?=h($item['name'])?></small><strong><?=h($item['value'])?></strong></div></div><?php endforeach;?></div></section><?php }
